[{"order":1,"type":"heading","text":"Global State Management in React Native: Architecture & Comparison"},{"order":2,"type":"paragraph","text":"Choosing the right state management solution in React Native is critical for maintaining high performance, especially on mobile devices with constrained memory and CPU limits. In this tutorial, we will explore four prominent state management architectures: Redux Toolkit, Zustand, Jotai, and Recoil."},{"order":3,"type":"subheading","text":"1. Redux Toolkit (RTK): Predictable and Structured"},{"order":4,"type":"paragraph","text":"Redux Toolkit is the standard, opinionated toolset for efficient Redux development. It reduces boilerplate and simplifies store setup. Below is an example of creating a counter slice in a React Native application."},{"order":5,"type":"code","text":"import { createSlice, configureStore } from '@reduxjs/toolkit';

const counterSlice = createSlice({
  name: 'counter',
  initialState: { value: 0 },
  reducers: {
    increment: state => { state.value += 1; },
    decrement: state => { state.value -= 1; },
  },
});

export const { increment, decrement } = counterSlice.actions;

export const store = configureStore({
  reducer: { counter: counterSlice.reducer },
});"},{"order":6,"type":"subheading","text":"2. Zustand: Minimalist and Hook-Centric"},{"order":7,"type":"paragraph","text":"Zustand provides a fast, scalable, and minimalist state management solution using a hook-based API. It requires no providers and significantly reduces boilerplate compared to traditional Redux."},{"order":8,"type":"code","text":"import create from 'zustand';

const useStore = create((set) => ({
  count: 0,
  increment: () => set((state) => ({ count: state.count + 1 })),
  decrement: () => set((state) => ({ count: state.count - 1 })),
}));

export default useStore;"},{"order":9,"type":"subheading","text":"3. Jotai: Atomic State Management"},{"order":10,"type":"paragraph","text":"Jotai takes an atomic approach inspired by Recoil. State is split into independent pieces called atoms. Derived states can be computed easily without unnecessary re-renders."},{"order":11,"type":"code","text":"import { atom, useAtom } from 'jotai';

export const textAtom = atom('Hello React Native');
export const uppercaseAtom = atom(
  (get) => get(textAtom).toUpperCase()
);

export const TextInputComponent = () => {
  const [text, setText] = useAtom(textAtom);
  return <TextInput value={text} onChangeText={setText} />;
};"},{"order":12,"type":"subheading","text":"4. Recoil: Graph-Based State Management"},{"order":13,"type":"paragraph","text":"Developed by Meta, Recoil utilizes a directed graph built on top of React components. It offers robust support for asynchronous selectors and complex data-fetching flows out of the box."},{"order":14,"type":"code","text":"import { atom, selector, useRecoilState, useRecoilValue } from 'recoil';

export const counterState = atom({
  key: 'counterState',
  default: 0,
});

export const doubleCounterState = selector({
  key: 'doubleCounterState',
  get: ({ get }) => {
    const count = get(counterState);
    return count * 2;
  },
});"},{"order":15,"type":"subheading","text":"Architectural Comparison and Best Practices"},{"order":16,"type":"bullet_point","text":"Redux Toolkit: Best for large enterprise apps requiring strict debugging, time-travel, and rigid architectural patterns."},{"order":17,"type":"bullet_point","text":"Zustand: Best for teams looking for high performance, low boilerplate, and simple global stores without React Context wrappers."},{"order":18,"type":"bullet_point","text":"Jotai: Best for fine-grained reactivity, avoiding unnecessary tree re-renders, and functional composition via atoms."},{"order":19,"type":"bullet_point","text":"Recoil: Best for React Native apps heavily reliant on asynchronous data selectors and tightly integrated with React suspense."}]
